css:
.outer-border {
  font-family: "Inter", sans-serif;
  font-size: 18px;
  background-color: var(--gray-200);
  border: 1.5px solid black;
  border-radius: 1rem;
  padding: 3rem;
  position: relative;
}

.inner-border {
  border: 10px solid var(--primary-500);
  border-radius: 1rem;
  padding: 5rem 3rem;
  background-color: var(--gray-100);
  text-align: center;
  position: relative;
}

.certificate-logo {
  position: absolute;
  top: 2rem;
  left: 2rem;
  height: 5rem;
}

.course-logo {
  position: absolute;
  top: 2rem;
  right: 2rem;
  height: 5rem;
}

.certificate-name {
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--primary-800);
  margin-bottom: 1.2rem;
}

.certificate-subtitle {
  font-size: 1.5rem;
  color: var(--gray-800);
  margin-bottom: 1.2rem;
}

.cursive-font {
  font-family: 'Brush Script MT', cursive;
  font-size: 2.5rem;
  font-weight: 600;
  color: var(--primary-600);
  margin: 2rem 0;
}

.certificate-footer {
  margin-top: 5rem;
  border-top: 1px solid var(--gray-300);
  padding-top: 2rem;
  color: var(--gray-900);
  font-size: 1rem;
  text-align: center;
}

.signature-title {
  font-size: 1.3rem;
  font-weight: 700;
  color: black;
  margin-top: 1.5rem;
}

.certificate-footer-item {
  margin-top: 1rem;
}

.certificate-divider {
  height: 2px;
  background-color: var(--gray-300);
  margin: 2rem 0;
  width: 60%;
  margin-left: auto;
  margin-right: auto;
}

.certificate-expiry {
  margin-top: 1rem;
  font-size: 0.95rem;
  color: var(--gray-700);
}


.certificate-divider-wide {
  width: 50%;
  margin: 1.5rem auto;
  height: 2px;
  background-color: var(--gray-400);
  border: none;
}

html:
{% set certificate = frappe.db.get_value("LMS Certificate", doc.name, ["name", "member", "issue_date", "expiry_date", "course"], as_dict=True) %}
{% set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) %}
{% set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name", "image"], as_dict=True) %}
{% set logo = frappe.db.get_single_value("Website Settings", "banner_image") %}
{% set instructors = frappe.get_all("Course Instructor", {"parent": doc.course}, pluck="instructor", order_by="idx") %}

<meta name="pdfkit-orientation" content="Landscape">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&display=swap" rel="stylesheet">

<div class="outer-border">
  <div class="inner-border">

    <!-- Top logos -->
    {% if logo %}
      <img src="{{ logo }}" class="certificate-logo">
    {% endif %}
    {% if course.image %}
      <img src="{{ course.image }}" class="course-logo">
    {% endif %}

    <div class="certificate-subtitle">
      {{ _("This certifies that") }}
    </div>

    <div class="certificate-name">
      {{ member.full_name }}
    </div>

    <div class="certificate-subtitle">
      {{ _("has successfully completed the course on") }}
      <b>{{ course.title }}</b>
      {{ _("on") }} {{ frappe.utils.format_date(certificate.issue_date, "medium") }}.
    </div>

    <table class="certificate-footer">
      <tr>
        {% if instructors %}
          <td>
            <div class="certificate-footer-item cursive-font">
              {% for i in instructors %}
                {{ frappe.db.get_value("User", i, "full_name") }}
                {% if not loop.last %}, {% endif %}
              {% endfor %}
            </div>
            <hr class="certificate-divider">
            <div class="text-center"> {{ _("Course Instructor") }} </div>
          </td>
        {% endif %}

        {% if certificate.expiry_date %}
          <td style="width: 30%"></td>
          <td class="certificate-expiry">
            <div class="certificate-footer-item">
              {{ frappe.utils.format_date(certificate.expiry_date, "medium") }}
            </div>
            <hr class="certificate-divider">
            <div class="text-center"> {{ _("Expiry Date") }} </div>
          </td>
        {% endif %}
      </tr>
    </table>

  </div>
</div>
